const shiftDate=(s,n)=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return localDate(d)};
const defaults=()=>({version:1,settings:{calories:1800,protein:160,carbs:null,fat:null,steps:10000,lifts:4,start:localDate(),goalWeight:null,age:null,bodyWeight:null,height:null,experience:'not-set'},days:{},groceries:{},prep:{},foodDiary:{}});
let offlineReady=false;let state=defaults(),storageOK=true,page='today',selectedDate=localDate(),mealDay=(new Date().getDay()+6)%7;
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));}catch(e){storageOK=false;}
