function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function commit(next,message){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;storageOK=true;if(message)notify(message);return true}catch(e){notify('Could not save. Export a backup, then free device storage.');return false}}
function validate(x){
 if(!x||x.version!==1||!x.settings||!x.days||typeof x.days!=='object'||Array.isArray(x.days))throw Error('Invalid backup');
 const next=defaults(),s=x.settings;
 for(const [k,min,max] of [['calories',1,10000],['protein',1,1000],['steps',1,100000],['lifts',1,7]]){if(!Number.isFinite(s[k])||s[k]<min||s[k]>max)throw Error('Invalid settings');next.settings[k]=s[k]}
 for(const [k,min,max] of [['age',18,100],['bodyWeight',50,1500],['height',36,100]]){if(s[k]!=null){if(!Number.isFinite(s[k])||s[k]<min||s[k]>max)throw Error('Invalid profile');next.settings[k]=s[k]}}next.settings.experience=['new','returning','regular'].includes(s.experience)?s.experience:'not-set';for(const k of ['carbs','fat']){if(s[k]!=null){if(!Number.isFinite(s[k])||s[k]<=0||s[k]>2000)throw Error('Invalid macro target');next.settings[k]=s[k]}}const dateOK=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v+'T12:00:00'))&&localDate(new Date(v+'T12:00:00'))===v;
 if(!dateOK(s.start))throw Error('Invalid date');next.settings.start=s.start;
 if(s.goalWeight!=null&&(!Number.isFinite(s.goalWeight)||s.goalWeight<1||s.goalWeight>1500))throw Error('Invalid goal');next.settings.goalWeight=s.goalWeight??null;
 for(const [date,d] of Object.entries(x.days)){if(!dateOK(date)||!d||typeof d!=='object')throw Error('Invalid day');let row={};for(const [k,max] of [['calories',20000],['protein',2000],['carbs',3000],['fat',2000],['steps',150000],['weight',1500],['waist',150],['reserve',10000],['runMinutes',300]]){if(d[k]!=null){if(!Number.isFinite(d[k])||d[k]<0||d[k]>max)throw Error('Invalid number');row[k]=d[k]}}
 if(d.targets){row.targets={};for(const k of ['calories','protein','carbs','fat']){const v=d.targets[k];if(v!=null&&(!Number.isFinite(v)||v<=0||v>20000))throw Error('Invalid saved target');row.targets[k]=v??null}if(!row.targets.calories||!row.targets.protein)throw Error('Invalid saved target')}row.loads={};if(d.loads&&typeof d.loads==='object')for(const [id,v] of Object.entries(d.loads)){if(!/^[a-z0-9-]{1,40}$/.test(id)||!v||typeof v!=='object')throw Error('Invalid load');if(v.weight!=null&&(!Number.isFinite(v.weight)||v.weight<0||v.weight>1500))throw Error('Invalid load');row.loads[id]={weight:v.weight??null,reps:String(v.reps??'').slice(0,60)}}row.exercises={};if(d.exercises&&typeof d.exercises==='object')for(const [id,v] of Object.entries(d.exercises))if(/^[a-z0-9-]{1,40}$/.test(id))row.exercises[id]=!!v;row.runComplete=!!d.runComplete;row.workout=!!d.workout;row.restaurant=!!d.restaurant;row.complete=!!d.complete;row.notes=String(d.notes??'').slice(0,3000);
 if(d.photo){if(typeof d.photo!=='string'||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(d.photo)||d.photo.length>900000)throw Error('Invalid image');row.photo=d.photo}
 next.days[date]=row;
 }
 for(const k of ['groceries','prep'])if(x[k]&&typeof x[k]==='object')for(const [id,v] of Object.entries(x[k]))if(/^[a-z0-9-]{1,40}$/.test(id))next[k][id]=!!v;
 next.training=cleanTraining(x.training);next.personal=cleanPersonal(x.personal);next.mealPlan=cleanMealPlan(x.mealPlan);next.foodDiary=FoodLedger.clean(x.foodDiary);for(const [date,diary] of Object.entries(next.foodDiary)){const total=FoodLedger.totals(diary.items);if(!next.days[date])throw Error('Missing food diary date');for(const k of ['calories','protein','carbs','fat']){const expected=diary.items.length?(diary.base[k]??0)+total[k]:diary.base[k];if(expected==null?next.days[date][k]!=null:next.days[date][k]==null||Math.abs(expected-next.days[date][k])>0.01)throw Error('Food diary totals do not match');}}return next;
}
const day=()=>state.days[selectedDate]||{};
const title=(eyebrow,heading,sub)=>`<div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p class="subtitle">${sub}</p>`;
