function weeklyReview(){
 const end=localDate(),rows=windowRows(end,7),final=rows.filter(([,d])=>d.complete&&d.calories!=null),tracked=final.filter(([,d])=>d.targets),onBudget=tracked.filter(([,d])=>d.calories<=d.targets.calories),proteinRows=final.filter(([,d])=>d.protein!=null&&d.targets),proteinHit=proteinRows.filter(([,d])=>d.protein>=d.targets.protein),mean=average(final,'calories'),prior=windowRows(shiftDate(end,-7),7),currentWeights=rows.filter(([,d])=>d.weight>0),priorWeights=prior.filter(([,d])=>d.weight>0),delta=currentWeights.length>=3&&priorWeights.length>=3?average(rows,'weight')-average(prior,'weight'):null;
 let headline=final.length<5?'Build a clearer picture':onBudget.length===tracked.length&&tracked.length>=5?'Your logging shows consistency':'A useful week to learn from';
 let guidance=final.length<5?'Log final totals on at least five days before using the weekly pattern to review your goals.':tracked.length<5?'Some older entries have no saved target. Their totals are retained, but historical goal comparisons are unavailable.':onBudget.length<tracked.length?'Your final calories were above the saved budget on some days. Review portions, meal timing and restaurant plans before deciding whether the goal needs changing.':'You stayed within the saved calorie budget on your completed days. Keep checking protein, energy and recovery alongside the numbers.';
 return `<section class="card"><div class="eyebrow">Updates from your actual records</div><h2 class="section-title">${headline}</h2><div class="grid"><div><strong class="metric">${final.length}<small> / 7 days</small></strong><p class="fine">Final food totals logged</p></div><div><strong class="metric">${mean==null?'—':fmt(Math.round(mean))}</strong><p class="fine">Average kcal · completed days only</p></div></div><p class="muted">${onBudget.length} / ${tracked.length} comparable days within calorie budget · ${proteinHit.length} / ${proteinRows.length} comparable days at protein target.</p><p>${guidance}</p><div class="macro-grid">${[['protein','Protein'],['carbs','Carbs'],['fat','Fat']].map(([key,label])=>{const value=average(final,key),count=final.filter(([,d])=>d[key]!=null).length;return `<div class="macro-cell"><span class="eyebrow">${label}</span><strong>${value==null?'—':Math.round(value)}<small> g/day</small></strong><p class="fine">${count} logged final days</p></div>`}).join('')}</div><p class="muted">${delta==null?'Weight trend needs at least three weigh-ins in each of two consecutive weeks.':`Your seven-day average is ${Math.abs(delta).toFixed(1)} lb ${delta<0?'lower':delta>0?'higher':'different'} than the previous week. This is an observation, not a prediction.`}</p><p class="fine">Feedback updates automatically as you log. Goal changes are reviewed by you, never silently applied after one high day. Saved targets preserve the meaning of past check-ins.</p><button class="secondary wide" data-go="settings">Review or update my goals →</button></section>`;
}
function allHistory(){const rows=Object.entries(state.days).sort(([a],[b])=>b.localeCompare(a)),pages=Math.max(1,Math.ceil(rows.length/14));historyPage=Math.min(historyPage,pages-1);const slice=rows.slice(historyPage*14,(historyPage+1)*14);return `<section class="card"><div class="row"><h2>Your daily history</h2><span class="pill">${rows.length} saved days</span></div><p class="fine">All saved dates are retained. Tap a date to review or edit its full check-in.</p>${rows.length?`<div class="scroll-table"><table><thead><tr><th>Date</th><th>kcal</th><th>Protein</th><th>Carbs</th><th>Fat</th><th>Weight</th><th>Status</th></tr></thead><tbody>${slice.map(([dt,d])=>`<tr><td><button class="secondary" data-edit="${dt}">${dt}</button></td><td>${d.calories??'—'}</td><td>${d.protein??'—'}</td><td>${d.carbs??'—'}</td><td>${d.fat??'—'}</td><td>${d.weight??'—'}</td><td>${d.complete?'Final':'In progress'}</td></tr>`).join('')}</tbody></table></div><div class="row history-controls"><button class="secondary" data-history="-1" ${historyPage===0?'disabled':''}>Newer</button><span class="fine">${historyPage+1} / ${pages}</span><button class="secondary" data-history="1" ${historyPage===pages-1?'disabled':''}>Older</button></div>`:'<p class="muted">Your first saved check-in will appear here.</p>'}</section>`}

function todayView(){
 const d=state.days[localDate()]||{},s=state.settings,left=s.calories-(d.calories||0),r=recommendation(localDate()),session=state.training?.[localDate()],plan=trainingPlan[r.plan];
 const macros=[['protein','Protein'],['carbs','Carbs'],['fat','Fat']];
 return title(new Date().toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric'}),'Make room for progress.','Your food, your movement, your next step.')+`${foodActions()}<div class="dashboard-grid"><section class="card hero dashboard-hero"><div><div class="eyebrow">${d.calories==null?'Today’s calorie budget':left>=0?'Calories remaining':'Above your budget'}</div><strong>${fmt(Math.abs(left))}</strong><p class="hint">${d.calories==null?'Ready for your first check-in':`${fmt(d.calories)} of ${fmt(s.calories)} kcal logged`}</p><button class="primary" data-go="log">${d.calories==null?'Start today’s log':'Update my day'} ↗</button></div><div class="ring" style="--fill:${Math.min(100,(d.calories||0)/s.calories*100)}%"><div class="ring-inner"><b>${d.calories==null?'—':Math.round(d.calories/s.calories*100)+'%'}</b><small>of calorie budget</small></div></div><div class="macro-grid dashboard-macros">${macros.map(([k,name])=>`<div class="macro-cell ${k}"><span class="eyebrow">${name}</span><strong>${d[k]==null?'—':fmt(d[k])}<small> g</small></strong>${s[k]?progressBar(d[k],s[k]):''}<p class="fine">${s[k]?`${s[k]} g target`:'No target set'}</p></div>`).join('')}</div></section><section class="card feature-card workout-focus"><div class="row"><span class="eyebrow">Your next move</span><span class="pill">${session?.finished?'Saved ✓':r.blocked?'Recovery':plan.kind==='strength'?'≈ 60 min':plan.kind==='run'?'20–30 min':'Rest day'}</span></div><h2>${session?.finished?'Session saved.':r.blocked?'Give yourself a breather.':plan.name}</h2><p class="muted">${session?.finished?`Next in your sequence: ${trainingPlan[(session.plan+1)%7].name}.`:r.reason}</p><div class="quick-actions"><button class="primary wide" data-go="train">${session?.finished?'Review workout':r.blocked?'Check my recovery':'Open my session'} →</button></div><p class="fine">The plan moves with you. Missed days carry forward.</p></section></div><div class="grid"><section class="card compact-card"><span class="eyebrow">Daily movement</span><p class="metric">${d.steps==null?'—':fmt(d.steps)}<small> steps</small></p>${progressBar(d.steps,s.steps)}<p class="hint">${d.steps==null?'Add steps in your check-in':`${fmt(Math.max(0,s.steps-d.steps))} to your goal`}</p></section><section class="card compact-card"><span class="eyebrow">Morning check-in</span><p class="metric">${d.weight??'—'}<small> lb</small></p><p class="hint">${d.weight!=null?'Saved for today':'A small habit. A clearer trend.'}</p><button class="secondary" data-go="${d.weight!=null?'progress':'log'}">${d.weight!=null?'View trend ↗':'Add weight ＋'}</button></section></div><details class="card"><summary>Today’s feedback <span class="pill">${d.complete?'Final totals':'In progress'}</span></summary>${dailyFeedback(d,s)}${d.restaurant?`<p>Restaurant dinner planned · ${fmt(d.reserve||800)} kcal reserved.</p>`:''}<p class="fine">Use Log for the full macro breakdown and to mark your day’s totals final.</p></details>${typeof todayMealShowcase==='function'?todayMealShowcase():''}<p class="fine">Saved on this device. Export a backup in Settings to keep a separate copy.</p>`;
}
