function trainingDate(){return shiftDate(localDate(),trainingDay-((new Date().getDay()+6)%7))}
function trainingTodayCard(){const plan=trainingPlan[(new Date().getDay()+6)%7];return `<section class="card training-teaser"><div class="eyebrow">On your training calendar</div><h2 class="section-title">${plan.name}</h2><p class="muted">${plan.kind==='strength'?'About 60 minutes · warm-up, lift, cool down':plan.focus}</p><button class="secondary wide" data-go="train">Open your session →</button></section>`}
function trainingProfileNote(){const s=state.settings;return `<div class="notice"><b>${s.experience==='new'?'Start with two sets':s.experience==='returning'?'Ease back into your routine':s.experience==='regular'?'Build from your current working loads':'Find your starting point'}</b><p>${s.experience==='new'?'For your first eight logged strength sessions, the coach starts with two sets per exercise. Keep technique comfortable before adding load.':s.experience==='returning'?'For your first eight logged strength sessions, the coach starts with two sets; use comfortable loads as you return. Build back only as recovery allows.':s.experience==='regular'?'Use the listed sets and a load that leaves 2–3 reps in reserve. Keep easy runs easy.':'Choose your experience in Settings to tailor the starting guidance. Begin light while you learn each movement.'}${s.age>=65?' Include supported balance practice and take extra recovery time when needed.':''}</p>${s.age?`<span class="fine">Your profile: age ${s.age}${s.bodyWeight?' · '+s.bodyWeight+' lb':''}. Loads are calibrated by effort, not calculated from body mass.</span>`:''}</div>`}
function trainView(){const p=trainingPlan[trainingDay],date=trainingDate(),d=state.days[date]||{},future=date>localDate(),done=p.exercises.filter(([id])=>d.exercises?.[id]).length,week=windowRows(localDate(),7),runs=week.filter(([,v])=>v.runComplete||v.runMinutes>0).length;
return title('Stronger, one session at a time.','Your training rhythm.','Four 60-minute strength sessions. Two easy runs. One day to recharge.')+`${trainingProfileNote()}<div class="day-strip training-strip" aria-label="Weekly training plan">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((name,i)=>`<button data-training-day="${i}" class="${trainingDay===i?'active':''}" aria-pressed="${trainingDay===i}">${name}<small>${['Upper','Lower','Run','Upper','Lower','Run','Rest'][i]}</small></button>`).join('')}</div><section class="card workout-hero"><div class="row"><span class="eyebrow">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][trainingDay]} · ${date}</span><span class="pill">${p.kind==='strength'?'≈ 60 min':p.kind==='run'?'20–30 min':'Recovery'}</span></div><h2>${p.name}</h2><p>${p.focus}</p>${p.kind==='strength'?`<div class="session-timeline"><span><b>8</b> min warm-up</span><span><b>45</b> min strength</span><span><b>7</b> min cool down</span></div>`:''}</section><div class="desktop-grid"><div>${p.kind==='strength'?`<section class="card"><h2>Warm up · 8 minutes</h2><p class="muted">5 minutes of easy walking or cycling, then gentle shoulder and hip movement. Do 1–2 lighter practice sets of your first lift before working sets.</p><p class="fine">Use a weight that leaves about 2–3 good reps in reserve. The hour is approximate; do not rush rests to finish.</p></section><section class="card"><div class="row"><h2>Your exercises</h2><span class="pill">${done} / ${p.exercises.length}</span></div>${p.exercises.map(([id,name,sets,cue,alt],i)=>`<div class="exercise">${exerciseVisual(trainingDay,id,name,date)}<label class="check"><input type="checkbox" data-exercise="${id}" ${d.exercises?.[id]?'checked':''} ${future?'disabled':''}><span>Completed all ${sets}</span></label><details><summary>Technique & alternative</summary><p>${cue}</p><p><b>Alternative:</b> ${alt}</p></details></div>`).join('')}<p class="fine">Guides alternate two reference photos, not full-motion video. For holds, maintain the aligned position rather than repeatedly moving. Check an exercise after completing its sets. These checks save for ${date}.</p></section><section class="card"><h2>Cool down · 7 minutes</h2><p class="muted">Walk slowly for 4 minutes, then spend 3 minutes on gentle, comfortable mobility for the muscles you trained.</p></section>`:p.kind==='run'?`<section class="card"><h2>Keep this one easy</h2><p class="muted">Choose the version that matches your current running ability. Start and finish with 5 minutes of walking. Stay at a pace where you can speak in sentences.</p><details open><summary>New or returning to running · 22 min</summary><p>5 min walk → 6 rounds of 1 min gentle jog + 1 min walk → 5 min walk. Walking the full session is a valid starting point.</p></details><details><summary>Already comfortable running · 25–30 min</summary><p>5 min walk → 15–20 min easy jog → 5 min walk. Keep it relaxed; no intervals or sprints in this plan.</p></details><p class="fine">Legs tired from yesterday? Replace the jog with an easy walk or rest. You can swap days while keeping at least one day between runs.</p></section><section class="card">${field('session-run-minutes','Minutes completed',d.runMinutes??'','number','max="300"')}<p class="fine">Includes walking intervals. Save only minutes you actually completed.</p></section>`:`<section class="card"><h2>Recovery is part of the plan.</h2><p class="muted">Take a full rest day, or enjoy an easy walk and 5–10 minutes of gentle mobility if you feel like it. There is no workout to make up today.</p><button class="secondary wide" data-go="meals">Get ready for the week →</button></section>`}${p.kind!=='rest'?`<button id="complete-session" class="primary wide" ${future?'disabled':''}>${future?'Upcoming session':p.kind==='strength'?(d.workout?'Session logged ✓':'Mark strength session complete'):(d.runComplete?'Update completed run':'Save completed run')}</button><p class="fine">Logs the selected date, ${date}. Use Log to correct an entry.</p>`:''}</div><div><section class="card"><h2>Find your working weight</h2><p class="muted">Age and body mass do not determine your lifting capacity. Begin with a light practice set. Choose a load that lets you complete the prescribed reps while still being able to do 2–3 more with good form.</p><p class="muted">If you cannot reach the bottom of the rep range cleanly, reduce the load. When all sets reach the upper end comfortably, increase by the smallest available increment next time. Record your actual weights below each guide.</p><p class="fine">Dumbbells: record the weight of one dumbbell. Barbell: total including the bar. Machine: displayed stack weight. Bodyweight exercises: leave blank or enter zero.</p></section><section class="card"><h2>Build up over six weeks</h2><div class="phase"><b>01–02 · Learn the rhythm</b><p>New to lifting? Use 2 sets per exercise and light loads. Keep runs as run/walk. Use the spare minutes for easy movement or finish early.</p></div><div class="phase"><b>03–04 · Add a little</b><p>When the current work feels comfortable, use the listed sets. Once every set reaches the top of its rep range with good form, try the smallest weight increase next time.</p></div><div class="phase"><b>05–06 · Stay consistent</b><p>Repeat the plan. For running, add 2–3 easy minutes only when recovering well; change duration before speed. Keep the run at 30 minutes or less for this block.</p></div><p class="fine">Repeat a week whenever needed. No need to progress every session. If fatigue builds, reduce a set or replace a run with a walk.</p></section><section class="card"><h2>Your week so far</h2><div class="row"><span class="muted">Strength · last 7 days</span><b>${week.filter(([,v])=>v.workout).length} / ${state.settings.lifts}</b></div><div class="row"><span class="muted">Runs · last 7 days</span><b>${runs} / 2</b></div><p class="fine">Your step target includes steps taken during runs. Exercise does not automatically increase your calorie budget.</p></section><section class="card"><h2>Make the plan work for you</h2><p class="muted">This is a general gym template with exercise alternatives. Start below your limit and recover between sessions. Stop movements that cause pain. Adjust for injuries or medical restrictions with a qualified professional.</p><p class="fine">The schedule is designed for your requested four-day routine. It is not a promise of a particular weight-loss result.</p><a class="fine" href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html" target="_blank" rel="noreferrer">CDC activity guidance ↗</a><br><a class="fine" href="https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/couch-to-5k-running-plan/" target="_blank" rel="noreferrer">NHS beginner running guidance ↗</a></section></div></div>`}
function bindTraining(){bindDemos();document.querySelectorAll('[data-training-day]').forEach(b=>b.onclick=()=>{trainingDay=Number(b.dataset.trainingDay);render()});document.querySelectorAll('[data-exercise]').forEach(b=>b.onchange=()=>{const date=trainingDate();if(date>localDate())return;const next=structuredClone(state);next.days[date]||={};next.days[date].exercises||={};next.days[date].exercises[b.dataset.exercise]=b.checked;if(commit(next))render();else b.checked=!b.checked});if($('#complete-session'))$('#complete-session').onclick=()=>{const date=trainingDate();if(date>localDate())return;const next=structuredClone(state);next.days[date]||={};if(trainingPlan[trainingDay].kind==='strength')next.days[date].workout=true;else{const input=$('#session-run-minutes'),n=Number(input.value);if(!Number.isFinite(n)||n<=0||n>300){notify('Enter completed minutes between 1 and 300.');return}next.days[date].runComplete=true;next.days[date].runMinutes=n}if(commit(validate(next),'Session saved'))render()};}

